export function getTutorPlan(exam:string,subject:string,topic:string):TutorPlan|undefined{
  const name=topicAliases[topic]||topic;
  if(exam==='NCEE') return subject==='English Language'?nceeEnglishPlans[name]:nceeMathPlans[name];
  return subject==='English Language'?beceEnglishPlans[name]:beceTutorPlans[name];
}

export function getTutorTopicNames(exam:string,subject:string):string[]{
 const plans=exam==='NCEE'?(subject==='English Language'?nceeEnglishPlans:nceeMathPlans):(subject==='English Language'?beceEnglishPlans:beceTutorPlans);
 return Object.keys(plans);
}
